```go
func TestLimiter_Burst(t *testing.T) {
	limiter := &Limiter{
		tokens:     100,
		maxTokens:  100,
		refillRate: 10,
		lastRefill: time.Now(),
	}

	for i := 0; i < 100; i++ {
		if !limiter.Allow() {
			t.Errorf("Allowed before last refill")
		}
	}

	time.Sleep(time.Second) // Wait for the refill period to elapse

	for i := 0; i < 100; i++ {
		if !limiter.Allow() {
			t.Errorf("Allowed after last refill")
		}
	}
}
```

This test case ensures that the `Allow` function behaves correctly under burst load by verifying that it allows requests before the refill period and after the refill period.

